<script setup lang="ts">
import {displayText,ruleVersionText} from '../api'
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import Icon from './Icon.vue'
import CampusImageMap from './CampusImageMap.vue'
import IncidentEvidencePanel from './IncidentEvidencePanel.vue'
import DeviceAnalysisPanel from './DeviceAnalysisPanel.vue'
import {useExecution,executionTypes,executionStatuses,resourceTypes,executionActive,type ExecutionTask} from '../execution'
import {metricValue,type EvidenceSnapshot,type DemoScenario} from '../evidence'
import { api, label, time } from '../api'
import { useSituation, layerOptions, typeNames, type MapTask, type Patrol, type Selection } from '../situation'
const props=defineProps<{initialSelection?:MapTask|null}>()
const emit=defineEmits<{'open-task':[task:MapTask];'open-evidence':[snapshot:EvidenceSnapshot];'open-execution':[task:ExecutionTask]}>()
const execution=useExecution(),executionTasks=execution.tasks,executionResources=execution.resources,executionSelected=execution.selected
function showExecution(task:ExecutionTask){execution.select(task.id);view.value='coordination';if(task.image_id)imageId.value=task.image_id;choose({kind:'building',id:task.target_building_id});layers.value.routes=true;layers.value.drone=true;layers.value.robot=true}
const {data,loading,failure,view,imageId,selection,focus,layers,patrolId,image,patrol,refresh,choose,restoreTask}=useSituation()
const busy=ref(false), actionError=ref(''), droneId=ref(''), targetId=ref('loc-training'), floor=ref('2F'), floorOpen=ref(false)
const preparingDemo=ref(false)
async function prepareDemo(){if(preparingDemo.value)return;preparingDemo.value=true;actionError.value='';try{const scenario=await api<DemoScenario>('/demo-scenarios/evt-008/prepare',{});await refresh(true);execution.select(scenario.root_task_id||'');select({kind:'building',id:scenario.building_id});view.value='map'}catch(e){actionError.value=(e as Error).message}finally{preparingDemo.value=false}}
const building=computed(()=>data.value?.spaces.find(s=>s.id===(selection.value?.kind==='building'?selection.value.id:device.value?.building_id||event.value?.building_id)))
const device=computed(()=>selection.value?.kind==='device'?data.value?.devices.find(d=>d.id===selection.value!.id):undefined)
const event=computed(()=>selection.value?.kind==='incident'?data.value?.incidents.find(i=>i.id===selection.value!.id):undefined)
const buildingDevices=computed(()=>data.value?.devices.filter(d=>d.building_id===building.value?.id)||[])
const buildingEvents=computed(()=>data.value?.incidents.filter(e=>e.building_id===building.value?.id)||[])
const relatedDevices=computed(()=>data.value?.devices.filter(d=>device.value?.related_device_ids.includes(d.id)||event.value?.device_ids.includes(d.id))||[])
const relatedEvents=computed(()=>data.value?.incidents.filter(e=>device.value?.incident_ids.includes(e.id))||[])
const online=computed(()=>data.value?.devices.filter(d=>d.status!=='offline').length||0)
const alarms=computed(()=>data.value?.devices.filter(d=>d.alarm).length||0)
const riskCount=(risk:string)=>data.value?.incidents.filter(i=>risk==='unassessed'?!['high','medium','low'].includes(i.risk_level):i.risk_level===risk).length||0
const drones=computed(()=>data.value?.devices.filter(d=>d.type==='drone')||[])
const robot=computed(()=>data.value?.devices.find(d=>d.type==='robot'))
const targets=computed(()=>data.value?.spaces.filter(s=>s.anchor)||[])
const selectedName=computed(()=>device.value?.name||event.value?.title||building.value?.name||'空间详情')
const timeline=computed(()=>[...(data.value?.incidents||[])].sort((a,b)=>new Date(b.triggered_at).getTime()-new Date(a.triggered_at).getTime()))
const evidenceComplete=(id:string)=>data.value?.evidence_checks?.some(check=>check.incident_id===id&&check.status==='completed')||false
const mapTaskComplete=(id:string)=>data.value?.tasks.some(task=>task.incident_ids.includes(id))||false
function eventProgress(id:string){const executions=executionTasks.value.filter(task=>task.incident_id===id);if(executions.some(executionActive))return '模拟执行中，待巡检结果';if(executions.some(task=>task.status==='completed'))return '模拟执行完成，待人工复核';if(evidenceComplete(id))return '证据核查完成，待模型研判';const latest=data.value?.evidence_checks?.find(check=>check.incident_id===id);if(latest&&['queued','running'].includes(latest.status))return '证据核查执行中';if(mapTaskComplete(id))return '已生成规则研判，待人工核查';if(latest)return `证据核查${label(latest.status)}，待重新核查`;return '待 Agent 研判'}
const selectedPatrols=computed(()=>data.value?.patrols.filter(p=>p.target_building_id===building.value?.id)||[])
const floorDevices=computed(()=>{const patterns:Record<string,RegExp>={'1F':/(一层|1层|1F)/i,'2F':/(二层|2层|2F)/i,'3F':/(三层|3层|3F)/i};return buildingDevices.value.filter(d=>patterns[floor.value]?.test(d.floor))})
const trendPath=computed(()=>{const values=device.value?.trend.map(t=>t.value)||[];if(!values.length)return '';const min=Math.min(...values),max=Math.max(...values);return values.map((v,i)=>`${i?'L':'M'}${12+i*216/Math.max(values.length-1,1)} ${62-(v-min)/Math.max(max-min,1)*48}`).join(' ')})
function select(item:Selection){choose(item);floorOpen.value=false}
function switchImage(){selection.value=null;focus.value=null}
async function task(action:'campus'|'building'|'anomalies'|'patrol'|'report'){
 if(!data.value||busy.value)return
 busy.value=true;actionError.value=''
 const campus=action==='campus', anomalous=action==='anomalies', planning=action==='patrol'
 const target=data.value.spaces.find(s=>s.id===targetId.value)
 const deviceIds=campus||anomalous?[]:planning?[droneId.value].filter(Boolean):device.value?[device.value.id]:event.value?event.value.device_ids:building.value?buildingDevices.value.map(d=>d.id):[]
 const incidentIds=campus||anomalous||planning?[]:event.value?[event.value.id]:device.value?device.value.incident_ids:building.value?buildingEvents.value.map(i=>i.id):[]
 const buildingId=campus||anomalous?null:planning?targetId.value:building.value?.id||null
 const sourceSelection:Selection|null=planning?{kind:'building',id:targetId.value}:campus||anomalous?null:selection.value
 const requestAction=action==='building'&&!buildingId?'report':action
 const instructions={campus:'分析当前杭州校区安全态势，核查全部演示风险与设备。',building:`分析${device.value?.name||building.value?.name||'当前区域'}风险，核查关联设备与事件。`,anomalies:'检查当前校园异常及离线设备，说明证据和待核实项。',patrol:`规划无人机巡检：${target?.name||'选定区域'}，核查任务条件。`,report:`生成${device.value?.name||building.value?.name||'杭州校区'}安全报告摘要（模拟）。`}
 try{const result=await api<MapTask>('/situation/tasks',{instruction:instructions[action],action:requestAction,source_view:view.value,image_id:planning?target?.anchor?.image_id||imageId.value:imageId.value,building_id:buildingId,device_ids:deviceIds,incident_ids:incidentIds,source_selection:sourceSelection});await refresh(true);emit('open-task',result)}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}
}
async function createComparisonScenario(){if(busy.value)return;busy.value=true;actionError.value='';try{const created=await api<{id:string}>('/scenarios/temperature-only/trigger',{});await refresh(true);select({kind:'incident',id:created.id})}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}}
async function createPatrol(){if(busy.value||!droneId.value||!targetId.value)return;busy.value=true;actionError.value='';try{const p=await api<Patrol>('/situation/patrols',{device_id:droneId.value,target_building_id:targetId.value});patrolId.value=p.id;execution.select('');imageId.value=p.image_id;layers.value.routes=true;layers.value.drone=true;await refresh(true)}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}}
async function confirmPatrol(){if(!patrol.value||busy.value)return;busy.value=true;try{await api<Patrol>(`/situation/patrols/${patrol.value.id}/confirm`,{});await refresh(true)}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}}
function showPatrol(p:Patrol){execution.select('');patrolId.value=p.id;imageId.value=p.image_id;view.value='coordination';layers.value.routes=true;layers.value.drone=true}
watch(()=>props.initialSelection,t=>{if(t&&data.value)restoreTask(t)})
watch(()=>patrol.value?.id,()=>{if(patrol.value){targetId.value=patrol.value.target_building_id;droneId.value=patrol.value.device_id}},{immediate:true})
let timer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{await refresh();droneId.value=patrol.value?.device_id||drones.value[0]?.id||'';targetId.value=patrol.value?.target_building_id||targetId.value;if(props.initialSelection)restoreTask(props.initialSelection);timer=setInterval(()=>{if(data.value?.patrols.some(p=>p.status==='running')||executionTasks.value.some(executionActive))refresh(true)},900)})
onUnmounted(()=>clearInterval(timer))
</script>

<template>
 <div class="situation-page">
  <div class="situation-topline"><div><span class="eyebrow">SKYDOME · CAMPUS SITUATION</span><h2>浙江交通职业技术学院 <span>杭州校区</span></h2></div><span class="demo-badge">演示数据</span><button class="icon-button" aria-label="刷新全域态势" @click="refresh()"><Icon name="refresh" :size="17"/></button></div>
  <div class="situation-tabs" role="tablist" aria-label="全域态势视图"><button v-for="entry in [{id:'overview',name:'全域态势总览',icon:'signal'},{id:'map',name:'数字孪生地图',icon:'map'},{id:'coordination',name:'空天地协同',icon:'flow'}]" :key="entry.id" role="tab" :aria-selected="view===entry.id" :class="{active:view===entry.id}" @click="view=entry.id as typeof view"><Icon :name="entry.icon" :size="17"/>{{displayText(entry.name)}}</button><span>杭州校区 · 其他校区预留</span></div>
  <div v-if="failure||actionError" class="situation-error" role="alert">{{displayText(actionError||failure)}}<button @click="actionError='';refresh()">重新加载</button></div>
  <div v-if="loading&&!data" class="loading-state">正在载入统一演示数据…</div>
  <template v-if="data">
   <div class="situation-metrics"><div><small>关联建筑区域</small><strong>{{data.spaces.length}}<span>处</span></strong></div><div><small>演示设备</small><strong>{{data.devices.length}}<span>台</span></strong></div><div><small>在线设备</small><strong class="aqua">{{online}}<span>/ {{data.devices.length}}</span></strong></div><div><small>风险事件</small><strong class="coral">{{data.incidents.length}}<span>起</span></strong></div><div><small>异常设备</small><strong class="amber">{{alarms}}<span>台</span></strong></div><div><small>历史地图巡检完成</small><strong>{{data.patrols.filter(p=>p.status==='completed').length}}<span>次</span></strong></div></div>
   <div class="demo-chain-entry"><div><strong>EVT-008 · TEMP-008 → 规则研判 → TASK-008</strong><p>首次准备写入独立演示事件；重复准备保留原证据和任务，不重复派发。</p></div><button class="outline-button" :disabled="preparingDemo" @click="prepareDemo">{{preparingDemo?'正在准备…':'准备 EVT-008 演示链路'}}</button></div>
   <div class="comparison-scenario-bar"><div><strong>DAY 03 · 对照场景</strong><span>新增单项温度异常：68.5℃、烟雾未触发、摄像机在线。保留已有事件与历史证据。</span></div><button class="outline-button" :disabled="busy" @click="createComparisonScenario">{{busy?'处理中…':'创建单温异常场景（模拟）'}}</button></div>
   <div class="situation-grid">
    <aside class="situation-left">
     <section class="situation-panel"><div class="situation-panel-title"><Icon name="shield" :size="16"/>风险等级分布 <span>模拟</span></div><div class="risk-bars"><div v-for="r in ['high','medium','low','unassessed']" :key="r"><span>{{label(r)}}</span><i><b :class="r" :style="{width:`${riskCount(r)/Math.max(data.incidents.length,1)*100}%`}"></b></i><strong>{{riskCount(r)}}</strong></div></div></section>
     <section class="situation-panel"><div class="situation-panel-title"><Icon name="map" :size="16"/>建筑区域 <span>{{data.spaces.length}}</span></div><button v-for="s in data.spaces" :key="s.id" class="space-list-item" :class="{chosen:building?.id===s.id}" @click="select({kind:'building',id:s.id})"><span class="space-symbol"><Icon name="home" :size="17"/></span><span><strong>{{displayText(s.name)}}</strong><small>{{s.anchor?'可定位 · 规划资料':'位置待核实'}}</small></span><Icon name="chevron" :size="12"/></button></section>
     <section class="situation-panel"><div class="situation-panel-title"><Icon name="device" :size="16"/>图层与设备 <span>模拟</span></div><label v-for="[key,title] in layerOptions" :key="key" class="layer-option"><input v-model="layers[key!]" type="checkbox" :aria-label="`${title}图层`"/><span>{{title}}</span><small v-if="typeNames[key!]">{{data.devices.filter(d=>d.type===key).length}}</small></label></section>
    </aside>
    <div class="situation-center">
     <div class="map-stage-header"><div><span class="live-dot"></span>{{view==='overview'?'校园空间态势':view==='map'?'数字孪生空间地图':'空天地协同监测'}}</div><select v-model="imageId" aria-label="选择校园底图" @change="switchImage"><option v-for="i in data.images" :key="i.id" :value="i.id">{{displayText(i.title)}}</option></select></div>
     <CampusImageMap v-if="image" :image="image" :spaces="data.spaces" :devices="data.devices" :incidents="data.incidents" :layers="layers" :selected="selection" :patrol="patrol" :execution-mission="executionSelected" :execution-resources="executionResources" :focus="focus" @select="select"/>
     <div class="image-provenance"><Icon name="info" :size="14"/><p>{{displayText(image?.description)}}<strong>学校发布的规划效果图 · 图片交互地图 · 非真实三维模型</strong></p><a v-if="image?.source_url" :href="image.source_url" target="_blank" rel="noopener">资料来源 ↗</a></div>
     <div class="map-agent-bar"><span class="agent-orb mini"><Icon name="spark" :size="18"/></span><div><strong>天亨 Agent</strong><small>携带空间与设备上下文，交给工作台分析</small></div><button class="primary-button" :disabled="busy" @click="task('campus')">分析校园态势 <Icon name="arrow" :size="14"/></button><button class="outline-button" :disabled="busy" @click="task('anomalies')">检查异常设备</button><button class="outline-button" :disabled="busy" @click="task('report')">区域安全报告</button></div>
     <section v-if="view==='coordination'" class="situation-panel coordination-panel"><div class="situation-panel-title"><Icon name="flow" :size="17"/>无人机模拟巡检 <span>模拟 · 12 秒演示</span></div><div class="patrol-steps"><span :class="{done:patrol}">01 选择设备与目标</span><span :class="{done:patrol}">02 生成航线</span><span :class="{done:patrol?.status!=='draft'&&patrol}">03 确认执行</span><span :class="{done:patrol?.status==='completed'}">04 结果与历史</span></div><div class="patrol-form"><label>巡检无人机<select v-model="droneId" aria-label="巡检无人机"><option v-for="d in drones" :key="d.id" :value="d.id">{{d.code}} · {{label(d.status)}} · {{d.battery??'—'}}%</option></select></label><label>目标建筑<select v-model="targetId" aria-label="巡检目标建筑"><option v-for="s in targets" :key="s.id" :value="s.id">{{displayText(s.name)}}</option></select></label><button class="outline-button" :disabled="busy||patrol?.status==='running'" @click="createPatrol">{{patrol?.status==='completed'?'重新生成巡检航线':'生成巡检航线'}}</button><button class="primary-button" :disabled="busy||patrol?.status!=='draft'" @click="confirmPatrol">确认巡检任务</button></div><div v-if="patrol" class="patrol-progress"><div><span>{{patrol.status==='draft'?'航线已生成 · 等待确认':patrol.status==='running'?'无人机正在沿演示航线巡检':'巡检完成'}} · {{data.spaces.find(s=>s.id===patrol?.target_building_id)?.name}}</span><strong>{{Math.round(patrol.progress)}}%</strong></div><progress :value="patrol.progress" max="100"></progress><small>{{patrol.id}}</small><p v-if="patrol.result" class="patrol-result"><Icon name="check" :size="16"/>{{displayText(patrol.result)}}</p></div><div v-else class="panel-hint">选择目标后生成航线，确认后才开始模拟巡检。路线不代表真实可飞行航线。</div><button class="text-button" :disabled="busy" @click="task('patrol')">交给 Agent 分析巡检计划 <Icon name="arrow" :size="13"/></button><details class="patrol-history" :open="data.patrols.length>0"><summary>巡检任务历史（{{data.patrols.length}}）</summary><button v-for="p in data.patrols.slice(0,8)" :key="p.id" @click="showPatrol(p)"><span>{{data.spaces.find(s=>s.id===p.target_building_id)?.name}}<small>{{time(p.created_at,true)}}</small></span><span>{{p.status==='draft'?'待确认':label(p.status)}} · {{Math.round(p.progress)}}%</span></button></details></section>
     <section v-if="view==='coordination'" class="situation-panel execution-map-cards"><div class="execution-section-heading"><div><h3>空天地协同执行</h3><p class="execution-muted">与任务中心共享同一份状态，实际执行均为模拟。</p></div><span>{{executionTasks.filter(executionActive).length}} 项执行中</span></div><div class="execution-resource-strip"><div v-for="resource in executionResources" :key="resource.id"><span>{{resourceTypes[resource.type]}}</span><strong>{{resource.code}} · {{label(resource.status)}}</strong><small>{{resource.current_task_code||'当前待命'}}{{resource.battery!==null?' · '+resource.battery+'%':''}}</small></div></div><div v-if="executionSelected" class="execution-map-active"><span class="execution-status" :class="executionSelected.status">{{executionStatuses[executionSelected.status]}}</span><h4>{{executionSelected.code}} · {{displayText(executionSelected.title)}}</h4><p>{{displayText(executionSelected.target_building_name)}} · {{executionSelected.resource_code||'资源待分配'}} · {{Math.round(executionSelected.progress)}}%</p><progress :value="executionSelected.progress" max="100" aria-label="地图执行任务进度"></progress><p v-if="executionSelected.task_type==='remote_sensing'">模拟区域核查，无真实遥感影像或飞行航线。</p><p v-else>归一化演示路线，非实际可飞行或可通行导航路径。</p><div class="execution-action-row"><button class="primary-button" @click="emit('open-execution',executionSelected)">打开执行详情</button><button class="text-button" @click="execution.select('')">收起执行路线，查看原巡检</button></div></div><button v-for="task in executionTasks.slice(0,8)" :key="task.id" class="execution-linked-task" @click="showExecution(task)"><span>{{task.code}} · {{displayText(task.title)}}<small>{{executionTypes[task.task_type]}} · {{task.resource_code||'资源待分配'}}</small></span><span class="execution-status" :class="task.status">{{executionStatuses[task.status]}}</span><b>{{Math.round(task.progress)}}%</b></button><p v-if="!executionTasks.length" class="execution-muted">可从已完成的证据核查或任务中心创建执行任务。</p></section>
     <div v-if="view==='coordination'" class="coordination-pair"><section class="situation-panel"><div class="situation-panel-title"><Icon name="device" :size="16"/>地面机器人 <span>模拟</span></div><template v-if="robot"><button class="device-inline" @click="select({kind:'device',id:robot.id})">{{robot.code}} · {{label(robot.status)}}<Icon name="chevron" :size="13"/></button><div v-for="metric in robot.metrics" :key="metric.label" class="datum"><span>{{metric.label}}</span><strong>{{metric.value}} {{metric.unit}}</strong></div><template v-if="data.robot_task"><div class="datum"><span>巡检任务</span><strong>{{displayText(data.robot_task.name)}}</strong></div><div class="datum"><span>任务目标</span><strong>{{data.spaces.find(s=>s.id===data?.robot_task.target_building_id)?.name}}</strong></div><div class="datum"><span>任务状态 / 进度</span><strong>{{label(data.robot_task.status)}} · {{data.robot_task.progress}}%</strong></div><progress :value="data.robot_task.progress" max="100" aria-label="机器人巡检进度"></progress></template><p class="panel-hint">模拟待命任务，无真实机器人控制。</p></template></section><section class="situation-panel"><div class="situation-panel-title"><Icon name="signal" :size="16"/>卫星遥感 <span>模拟</span></div><div class="datum"><span>任务状态</span><strong>{{data.satellite.status}}</strong></div><div class="datum"><span>覆盖区域</span><strong>{{displayText(data.satellite.coverage)}}</strong></div><div class="datum"><span>演示更新时间</span><strong>{{time(data.satellite.updated_at,true)}}</strong></div><p class="panel-hint">{{displayText(data.satellite.note)}}</p></section></div>
    </div>
    <aside class="situation-right">
     <section v-if="selection" class="situation-panel entity-drawer" aria-label="空间与设备详情"><div class="situation-panel-title"><Icon name="pin" :size="16"/>{{selection.kind==='device'?'设备详情':selection.kind==='incident'?'事件详情':'建筑空间详情'}}<button class="icon-button" aria-label="关闭地图详情" @click="selection=null"><Icon name="close" :size="15"/></button></div><div class="entity-heading"><span class="demo-badge">{{selection.kind==='building'?'学校规划资料':'模拟'}}</span><h3>{{displayText(selectedName)}}</h3></div>
      <template v-if="selection.kind==='building'&&building"><img v-if="building.detail_image" class="building-detail-image" :src="building.detail_image" :alt="`${building.name}规划透视图`"/><p class="panel-hint">规划效果图，非建成实景。</p><div class="datum"><span>用途</span><strong>{{building.usage}}</strong></div><div v-if="building.area_sqm" class="datum"><span>资料建筑面积</span><strong>约 {{building.area_sqm}} ㎡</strong></div><div class="datum"><span>楼层资料</span><strong>{{displayText(building.floors_note)}}</strong></div><p class="verification-note">{{displayText(building.verification)}}</p><p class="panel-hint">{{displayText(building.source_note)}}</p><button class="outline-button" @click="floorOpen=!floorOpen">{{floorOpen?'收起楼层示意':'进入建筑空间 · 模拟'}}</button><div v-if="floorOpen" class="floor-demo"><strong>模拟 楼层示意</strong><p>仅演示设备关联，不表示真实楼层或平面布局。</p><div class="floor-tabs"><button v-for="f in ['1F','2F','3F']" :key="f" :class="{active:floor===f}" @click="floor=f">{{f}}</button></div><div class="floor-grid"><span>模拟通道</span><button v-for="d in floorDevices" :key="d.id" @click="select({kind:'device',id:d.id})">{{d.code}}</button><small v-if="!floorDevices.length">此演示楼层未分配设备</small></div></div><h4>关联设备 · 模拟</h4><button v-for="d in buildingDevices" :key="d.id" class="drawer-row" @click="select({kind:'device',id:d.id})"><span>{{d.code}}<small>{{displayText(d.name)}}</small></span><span class="status-badge" :class="d.status">{{label(d.status)}}</span></button><p v-if="!buildingDevices.length" class="panel-hint">暂无关联演示设备</p><h4>当前风险事件</h4><button v-for="e in buildingEvents" :key="e.id" class="drawer-row" @click="select({kind:'incident',id:e.id})">{{e.code?e.code+' · ':''}}{{displayText(e.title)}}<span class="risk-pill" :class="e.risk_level">{{label(e.risk_level)}}</span></button><p v-if="!buildingEvents.length" class="panel-hint">暂无关联演示事件，不代表实际无风险。</p><h4>最近巡检</h4><button v-for="p in selectedPatrols.slice(0,2)" :key="p.id" class="drawer-row" @click="showPatrol(p)">{{time(p.created_at,true)}} · {{p.status==='draft'?'待确认':label(p.status)}}</button><p v-if="!selectedPatrols.length" class="panel-hint">暂无模拟巡检记录</p></template>
      <template v-if="device"><div class="device-code">{{device.code}}<small v-if="executionResources.find(resource=>resource.device_id===device?.id)"> · 调度资源 {{executionResources.find(resource=>resource.device_id===device?.id)?.code}}</small></div><div class="datum"><span>设备类型</span><strong>{{typeNames[device.type]||device.type}}</strong></div><div class="datum"><span>运行状态</span><span class="status-badge" :class="device.status">{{label(device.status)}}</span></div><div class="datum"><span>所属区域</span><strong>{{displayText(building?.name||'校园公共区域')}}</strong></div><div class="datum"><span>演示楼层</span><strong>{{displayText(device.floor||'室外 / 不适用')}}</strong></div><div class="datum"><span>最后更新</span><strong>{{time(device.last_seen,true)}}</strong></div><div class="datum"><span>告警状态</span><strong>{{device.alarm?'存在演示告警':'无演示告警'}}</strong></div><h4>当前监测数据</h4><div v-for="m in device.metrics" :key="m.label" class="device-metric"><span>{{m.label}}<small class="metric-source-time">{{time(m.observed_at,true)}} · {{label(m.quality)}}</small></span><strong>{{metricValue(m)}}</strong></div><div v-for="reference in device.references||[]" :key="reference.rule_id" class="assessment-reference"><strong>{{displayText(reference.reference_label)}}</strong><p>{{displayText(reference.source_label)}} · {{ruleVersionText(reference.rule_version)}}</p></div><p v-if="!device.references?.length" class="panel-hint">未配置此设备的演示参考规则，不能推断正常范围。</p><DeviceAnalysisPanel v-if="device" :device-id="device.id" :source-view="view" :image-id="device.anchor?.image_id||null" @open-evidence="emit('open-evidence',$event)" @select-event="select({kind:'incident',id:$event})"/><h4>设备历史趋势（跨事件·模拟）</h4><svg v-if="device.trend.length" class="trend-chart" viewBox="0 0 240 76" role="img" :aria-label="`${device.name}演示趋势：${device.trend.map(t=>t.value).join('，')}`"><path d="M12 14H228M12 38H228M12 62H228" stroke="#2b425c" fill="none"/><path :d="trendPath" stroke="#65d7e5" stroke-width="2" fill="none"/></svg><div v-if="device.trend.length" class="trend-labels"><span>{{time(device.trend[0]?.time)}}</span><span>{{time(device.trend.at(-1)?.time)}}</span></div><p v-else class="panel-hint">暂无趋势数据，不推断为正常。</p><h4>关联设备</h4><button v-for="d in relatedDevices" :key="d.id" class="drawer-row" @click="select({kind:'device',id:d.id})">{{d.code}} · {{displayText(d.name)}}<Icon name="chevron" :size="12"/></button><p v-if="!relatedDevices.length" class="panel-hint">暂无关联设备</p><h4>关联事件</h4><button v-for="e in relatedEvents" :key="e.id" class="drawer-row" @click="select({kind:'incident',id:e.id})">{{e.code?e.code+' · ':''}}{{displayText(e.title)}}<span class="risk-pill" :class="e.risk_level">{{label(e.risk_level)}}</span></button><p v-if="!relatedEvents.length" class="panel-hint">暂无关联事件</p></template>
      <IncidentEvidencePanel v-if="event" :key="event.id" :incident-id="event.id" :source-view="view" :image-id="imageId" @open-snapshot="emit('open-evidence',$event)" @select-device="select({kind:'device',id:$event})"/>
      <button v-if="!event&&!device" class="primary-button entity-agent" :disabled="busy" @click="task('building')"><Icon name="spark" :size="16"/>{{selection.kind==='building'?'分析当前建筑风险':'Agent 分析'}}</button>
     </section>
     <template v-else><section class="situation-panel"><div class="situation-panel-title"><Icon name="risk" :size="16"/>实时风险事件 <span>模拟</span></div><button v-for="e in data.incidents" :key="e.id" class="event-list-item" @click="select({kind:'incident',id:e.id})"><span class="event-level" :class="e.risk_level"></span><span><strong>{{e.code?e.code+' · ':''}}{{displayText(e.title)}}</strong><small>{{time(e.triggered_at)}} · {{label(e.status)}}</small></span><Icon name="chevron" :size="13"/></button></section><section class="situation-panel"><div class="situation-panel-title"><Icon name="device" :size="16"/>设备运行状态 <span>{{online}} / {{data.devices.length}}</span></div><button v-for="d in data.devices" :key="d.id" class="status-device-row" @click="select({kind:'device',id:d.id})"><span>{{d.code}}</span><span class="status-badge" :class="d.status">{{label(d.status)}}</span></button></section><section class="situation-panel"><div class="situation-panel-title"><Icon name="spark" :size="16"/>Agent 风险研判</div><p class="panel-hint">基于统一演示数据生成规则研判，保存建筑、设备及事件上下文。</p><button class="text-button" :disabled="busy" @click="task('campus')">开始校园风险研判 <Icon name="arrow" :size="13"/></button></section></template>
     <section class="situation-panel execution-map-cards"><div class="situation-panel-title"><Icon name="task" :size="16"/>执行任务 <span>{{executionTasks.length}}</span></div><button v-for="task in executionTasks.slice(0,3)" :key="task.id" class="execution-linked-task" @click="emit('open-execution',task)"><span>{{task.code}} · {{displayText(task.title)}}<small>{{executionStatuses[task.status]}} · {{Math.round(task.progress)}}%</small></span><Icon name="chevron" :size="13"/></button><p v-if="!executionTasks.length" class="panel-hint">暂无执行任务，可从证据核查结果创建。</p></section>
     <section class="situation-panel task-summary"><div class="situation-panel-title"><Icon name="task" :size="16"/>历史地图分析 <span>{{data.tasks.length}}</span></div><button v-for="t in data.tasks.slice(0,3)" :key="t.id" class="drawer-row" @click="emit('open-task',t)"><span>{{displayText(t.instruction)}}<small>{{time(t.created_at)}} · {{label(t.status)}}</small></span><Icon name="chevron" :size="12"/></button><p v-if="!data.tasks.length" class="panel-hint">暂无地图研判任务</p></section>
    </aside>
   </div>
   <section class="situation-timeline situation-panel"><div class="situation-panel-title"><Icon name="clock" :size="16"/>安全事件时间轴 <span>模拟 · {{time(data.updated_at)}} 更新</span></div><div class="timeline-cards"><button v-for="e in timeline" :key="e.id" @click="select({kind:'incident',id:e.id})"><small>{{time(e.triggered_at,true)}}</small><strong><i :class="e.risk_level"></i>{{e.code?e.code+' · ':''}}{{displayText(e.title)}}</strong><span>{{label(e.status)}} · {{eventProgress(e.id)}}</span><div class="event-processing"><b class="done">发现事件</b><b :class="{done:evidenceComplete(e.id)||mapTaskComplete(e.id)}">{{evidenceComplete(e.id)?'证据核查':'规则核查'}}</b><b>人工核查</b></div></button></div></section>
  </template>
 </div>
</template>
